bytecode=''

account = '0xe1DC13cD7E733B18A7820C82a5Cec04E96422b13'
private_key = '0x3081c97150dd05bf89edf46d41150aa335f6218d357e5907a371bc52085d9c0c'

Contract = w3.eth.contract(abi=abi, bytecode=bytecode)

transaction = Contract.constructor().build_transaction({
    'from': account,
    'nonce': w3.eth.get_transaction_count(account),
    'gas': 2000000,
    'gasPrice': w3.to_wei('5', 'gwei')
})

signed_txn = w3.eth.account.sign_transaction(transaction, private_key)

txn_hash = w3.eth.send_raw_transaction(signed_txn.raw_transaction)
txn_receipt = w3.eth.wait_for_transaction_receipt(txn_hash, timeout=600, poll_latency=2)
